    if not n.startswith(('CI-PL','LCI')):
        p=pdfs.parse_pi(n); pis[p['po']]=p
# compare CI vs PI
for c in cis:
    p=pis.get(c['po'])
    if not p: print('no PI for',c['po'],c['n']); continue
    pq={r['item']:r['qty'] for r in p['rows']}
    for r in c['rows']:
        if r['item'] not in pq: print('item not in PI',c['n'],r['item'])
        elif pq[r['item']]!=r['qty']: print('qty differs',c['n'],r['item'],pq[r['item']],r['qty'])
